def ejecutar_agente(objetivo, max_pasos=5):
    paso = 0
    while paso < max_pasos:
        paso += 1
        # 1. El LLM decide si llama herramienta o emite respuesta
        decision = "FINAL_ANSWER" if paso == 2 else "CALL_TOOL"
        if decision == "FINAL_ANSWER":
            return f"Objetivo cumplido en el paso {paso}."
    return "Límite de pasos alcanzado sin finalizar."
